package main
const page = `<!DOCTYPE html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Project Hub • Alpha Experiment 01</title><style>
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 80% 0%,#28344c,#080b13 58%);color:#f2f5fe;font:15px system-ui,Segoe UI,sans-serif}header{padding:26px 5vw;border-bottom:1px solid #32394e;display:flex;justify-content:space-between;gap:10px}h1{font-size:29px;margin:10px 0}h2{margin:0 0 10px}main{max-width:1450px;margin:auto;padding:25px 5vw}.muted{color:#a3aec3}.tag{display:inline-block;border:1px solid #526078;border-radius:18px;padding:5px 10px;font-size:12px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,370px),1fr));gap:20px}.card{padding:0;background:#151d2b;color:white;border:1px solid #39465f;text-align:left;font:inherit;border-radius:13px;overflow:hidden;cursor:pointer}.card:hover,.card:focus-visible{border-color:#70cfff;outline:none;transform:translateY(-2px)}.poster{height:215px;background:linear-gradient(115deg,#22456c,#1d1b38);display:grid;place-items:center;position:relative}.poster.teams{background:linear-gradient(115deg,#43335b,#182b45)}.poster .symbol{font-size:76px;color:#91dfff}.poster .tag{position:absolute;bottom:14px;left:14px;background:#0b1526df}.pad{padding:18px}.pad p{overflow-wrap:anywhere}.workspace{display:none}.bar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:12px 0 22px}.panel{padding:18px;background:#151d2b;border:1px solid #39465f;border-radius:12px}.cols{display:grid;grid-template-columns:1.5fr 1fr;gap:20px}@media(max-width:850px){.cols{grid-template-columns:1fr}}button.action,a.action{background:#2d405e;color:white;padding:10px 14px;border:1px solid #526e93;border-radius:8px;text-decoration:none;font:inherit;cursor:pointer}button.action:disabled{opacity:.4;cursor:not-allowed}button.action:hover:not(:disabled){background:#466384}a{color:#99dafa}iframe{width:100%;height:520px;background:#fff;border:1px solid #39465f;border-radius:9px}pre{font:12px Consolas,monospace;background:#080d16;color:#d5e5f7;padding:16px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:350px;overflow:auto}
</style><header><strong>◈ PROJECT HUB <span class="muted">/ alpha-experment01</span></strong><span class="tag">ISOLATED TEST</span></header><main><section id="library"><p class="muted">GITHUB REPOSITORIES · RUNNING ALPHA WORKSPACES</p><h1>Your Projects</h1><p class="muted">Select a project to open its real Alpha application. No simulated live status.</p><div id="cards" class="grid"></div></section><section id="workspace" class="workspace"><div class="bar"><button class="action" id="back">← Library</button><h1 id="heading"></h1><span class="tag" id="state"></span></div><div class="cols"><div class="panel"><h2>Running Alpha · Live application</h2><p class="muted" id="previewNote"></p><div class="bar"><button id="start" class="action">▶ Start Alpha</button><button id="stop" class="action">■ Stop Alpha</button><a id="open" class="action" target="_blank" rel="noopener">Open full screen ↗</a></div><iframe id="frame" title="Running project Alpha application" referrerpolicy="no-referrer"></iframe><p class="muted">This is the real application at its isolated localhost port. If browser framing is restricted, use Open full screen.</p></div><div class="panel"><h2>Repository / selected version</h2><div id="meta"></div><h3>Process and build logs</h3><pre id="logs"></pre></div></div></section></main>
<script>
const $=s=>document.querySelector(s);let projects=[],selected=null,frameKey="";
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function render(){document.querySelector("#cards").innerHTML=projects.map(p=>'<button class="card" data-id="'+esc(p.id)+'"><div class="poster '+esc(p.id)+'"><span class="symbol">'+(p.id==="dashboard"?"▣":"◎")+'</span><span class="tag">'+esc(p.status)+'</span></div><div class="pad"><h2>'+esc(p.name)+'</h2><p class="muted">'+esc(p.repo)+'</p><p>Alpha '+esc(p.commit||"not checked out")+'</p></div></button>').join("");document.querySelectorAll(".card").forEach(b=>b.onclick=()=>{selected=b.dataset.id;frameKey="";show()});if(selected)show()}
function show(){let p=projects.find(p=>p.id===selected);if(!p)return;$("#library").style.display="none";$("#workspace").style.display="block";$("#heading").textContent=p.name;$("#state").textContent=p.status;$("#open").href=p.url;$("#meta").innerHTML='<p><strong>GitHub</strong> <a target="_blank" rel="noopener" href="'+esc(p.repo)+'">Repository ↗</a></p><p><strong>Alpha branch:</strong> '+esc(p.branch)+'</p><p><strong>Local commit:</strong> '+esc(p.commit||"Unavailable")+'</p><p><strong>Checkout:</strong> '+esc(p.path)+'</p><p><strong>Managed PID:</strong> '+esc(p.pid||"Not running")+'</p>';
$("#previewNote").textContent=p.error||("This isolated instance runs at "+p.url);
$("#start").disabled=!p.ready||["running","starting","building","stopping"].includes(p.status);$("#stop").disabled=!p.pid;
$("#logs").textContent=p.logs||"No runs yet.";
const key=p.id+"-"+p.pid+"-"+p.status;if(key!==frameKey){frameKey=key;if(p.status==="running"){$("#frame").src=p.url;$("#frame").style.display="block"}else{$("#frame").removeAttribute("src");$("#frame").style.display="none"}}
}
$("#back").onclick=()=>{selected=null;$("#workspace").style.display="none";$("#library").style.display="block"};
async function action(type){if(!selected)return;let p=projects.find(p=>p.id===selected);if(type==="stop"&&!confirm("Stop only the "+p.name+" Alpha instance started by this Project Hub?"))return;try{let res=await fetch("/api/"+type+"?id="+encodeURIComponent(selected),{method:"POST",headers:{"Content-Type":"application/json"},body:"{}"});let data=await res.json();if(!res.ok)throw Error(data.error||"Request failed");await refresh()}catch(e){alert(e.message)}}
$("#start").onclick=()=>action("launch");$("#stop").onclick=()=>action("stop");
async function refresh(){try{let r=await fetch("/api/projects",{cache:"no-store"});if(!r.ok)throw Error("server error");projects=await r.json();render()}catch(e){document.querySelector("#cards").textContent="Project Hub backend unavailable: "+e.message}}
refresh();setInterval(refresh,2000);
</script></html>`
